RCT_EXPORT_MODULE()

+ (BOOL)requiresMainQueueSetup
{
  return NO;
}

/**
 * Unchanged from previous releases. Note that `walkme_item_action` is
 * deliberately absent: the WalkMe iOS SDK's `WMItemCallbacksDelegate` has no
 * item-action callback, so iOS has never emitted that event. Android does.
 */
- (NSArray<NSString *> *)supportedEvents
{
  return @[ @"walkme_item_presented", @"walkme_item_dismissed", @"walkme_analytics_event" ];
}

#pragma mark - Lifecycle

RCT_EXPORT_METHOD(start:(NSDictionary *)options)
{
  dispatch_async(dispatch_get_main_queue(), ^{
    [WMRNSdkProvider start:options];
  });
}

RCT_EXPORT_METHOD(stop)
{
  [WMRNSdkProvider stop];
}

RCT_EXPORT_METHOD(restart)
