#pragma mark - Callbacks

/**
 * Dispatched to main so this runs AFTER start()'s queued block on the same
 * serial queue. Otherwise this runs synchronously before start() and the
 * delegate is dropped when start() initializes the SDK.
 */
RCT_EXPORT_METHOD(setItemInfoListener:(BOOL)enable)
{
  __weak RNWalkMeSdk *weakSelf = self;
  dispatch_async(dispatch_get_main_queue(), ^{
    if (!enable) {
      [WMRNSdkProvider setItemInfoHandler:nil];
      return;
    }
    [WMRNSdkProvider setItemInfoHandler:^(NSString *eventName, NSDictionary *body) {
      [weakSelf sendEventWithName:eventName body:body];
    }];
  });
}

/** See `setItemInfoListener:` — same ordering requirement relative to `start`. */
RCT_EXPORT_METHOD(setAnalyticsListener:(BOOL)enable)
{
  __weak RNWalkMeSdk *weakSelf = self;
  dispatch_async(dispatch_get_main_queue(), ^{
    if (!enable) {
      [WMRNSdkProvider setAnalyticsHandler:nil];
      return;
    }
    [WMRNSdkProvider setAnalyticsHandler:^(NSDictionary *body) {
      [weakSelf sendEventWithName:@"walkme_analytics_event" body:body];
    }];
  });
}

#pragma mark - Teardown

/**
 * A React instance reload deallocates this module but not the WalkMe SDK
 * singleton, which would otherwise keep invoking a handler that captures a dead
 * emitter. Mirrors `WalkMeSdkBridge.invalidate()` on Android.
 */
- (void)invalidate
{
  dispatch_async(dispatch_get_main_queue(), ^{
    [WMRNSdkProvider setItemInfoHandler:nil];
    [WMRNSdkProvider setAnalyticsHandler:nil];
  });
  [super invalidate];
}

